/* prun: the pass map of lean/Pass.lean iterated from Ph.z 0 0 2.  A pass goes from one zigzag start
 * (y or Y with a >= 3, r >= 2) to the next in one affine step, away from the line r = a/3 (the boundary where
 * both blocks run out together, which holds the halting rows); near it, and for everything else, frun's jumps
 * are used (sweeps and zigzags whole, otherwise one case of next, c/fcases.h).  The 13 cases are proved for all
 * sizes in lean/Pass.lean (generated by py/gen_pass.py from this file's passv mode).
 *
 * Write a = 3q + e at a zigzag start t(a, j, r):
 *   drain   r <= q - 1:  t(a, j, r)  ->  t(a - 3r + 1, 0, 4r + 2j + 2)       j + 4r - 1 frames
 *   growth  r >= q + 7:  t(a, j, r)  ->  t'(4q + 2j + c, 0, r - q - d)        3q + (j + f)/2 frames
 *                        with (t', c, d, f) from the table G below (Y with e = 2: Y(a, j, r) -> y(5, j + 2q + 2, r - q - 1))
 *
 *   prun check N            N passes, each fast pass compared with the same frames taken by frun's jumps (exit 1 on
 *                           a mismatch)
 *   prun run N EVERY [D]    N passes; at every EVERY-th zigzag start a line "passes frames steps tag a j r ..."; with
 *                           D >= 0 every zigzag start within D of a halting row (y(3k+1, 2m, k+2+d), Y(3k+1, 2m, k+3+d);
 *                           d = 0 halts) is printed, and at the end the statistics of py/near.py (hexp, h2, hist)
 *   prun scout N EVERY [D]  as run with the state only (no frame or step counts; faster), the same lines
 *   prun lean N             where N calls of `pass` of lean/Pass.lean end (for its native_decide theorem)
 *   prun rate SEED M P N0   M random orbits of P passes each from a random zigzag start y(a, 0, r) or Y(a, 0, r) with
 *                           a + r = N0: the zigzag starts by distance d to a halting row (a = 1 mod 3, j even),
 *                           the sum of 1/(a + j + r), and the halts (an orbit stops at its halt)
 *   prun passv              for py/gen_pass.py: the jumps of a pass from each "t a j r" on stdin
 *   STOPF=F prun run ...    stop at the first zigzag start at or after frame F
 * A pass is counted at each zigzag start (the first one comes after 4 jumps from Ph.z 0 0 2).
 * Values are 64-bit (exit 2 before an overflow); frames and steps are 128-bit.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
typedef long long I;
typedef unsigned __int128 W;
#include "fcases.h"
static const char TAG[] = "zywuZYWU";
enum { z, y, w, u, Z, Y, Wt, U };

/* frun's jump (c/frun.c); returns frames, 0 on a halt; lastcode: the case of next (0..77), or 100 sweep w/W,
   101 sweep u/U, 102 zigzag */
static int lastcode;
static I jump(int *t, I v[3], W *st, int *hc) {
    I a = v[0], b = v[1], c = v[2], k;
    lastcode = 100 + ((*t == w || *t == Wt) ? 0 : (*t == u || *t == U) ? 1 : 2);
    if ((*t == w || *t == Wt) && b >= 2 && c >= 1) { k = b / 2; v[0] = a + 4 * k; v[1] = b - 2 * k; *st = (W)6 * k; return k; }
    if ((*t == u && b >= 1) || (*t == U && a >= 1 && b >= 1)) { v[1] = 0; v[2] = c + 2 * b; *st = (W)4 * b; return b; }
    if ((*t == y || *t == Y) && a >= 3 && c >= 2) {
        k = a / 3; if (c - 1 < k) k = c - 1;
        v[0] = a - 3 * k; v[1] = b + 2 * k; v[2] = c - k;
        *st = (W)k * (W)(4 * b + 9) + (W)4 * k * (k - 1); return 2 * k;
    }
    int r = fc_step(t, v, st); lastcode = r;
    if (r < 0) { *hc = -1 - r; return 0; }
    return 1;
}
static int zstart(int t, I v[3]) { return (t == y || t == Y) && v[0] >= 3 && v[2] >= 2; }

/* growth table: [Y?][e][j odd] = t', c, d, f (2 * frames constant), s0, s1, s2 (steps s0 + s1 q + s2 j + 4q^2 + 4qj) */
static const int G[2][3][2][7] = {
  { { {y, 2, 1, 8, 17, 19, 7}, {y, 5, 4, 7, 15, 19, 7} },
    { {y, 7, 4, 8, 20, 19, 7}, {y, 4, 1, 9, 22, 19, 7} },
    { {Y, 2, 1, 6, 29, 19, 7}, {Y, 5, 4, 5, 27, 19, 7} } },
  { { {y, 5, 1, 6, 17, 19, 7}, {y, 8, 4, 5, 15, 19, 7} },
    { {y, 11, 5, 14, 47, 27, 11}, {y, 8, 2, 15, 49, 27, 11} },
    { {0} , {0} } } };

/* one pass from a zigzag start if it is away from the boundary: returns frames (>0), or 0 if not applicable */
static W pass(int *t, I v[3], W *st) {
    I a = v[0], j = v[1], r = v[2], q = a / 3, e = a % 3;
    int big = *t == Y;
    if (r <= q - 1) {
        v[0] = a - 3 * r + 1; v[1] = 0; v[2] = 4 * r + 2 * j + 2;
        *st = 3 + (W)2 * j + (W)9 * r + (W)4 * j * r + (W)4 * r * r;
        return (W)j + (W)4 * r - 1;
    }
    if (r >= q + 7) {
        if (big && e == 2) {
            v[0] = 5; v[1] = j + 2 * q + 2; v[2] = r - q - 1; *t = y;
            *st = 35 + (W)13 * q + (W)4 * j + (W)4 * q * q + (W)4 * q * j;
            return 2 + (W)2 * q;
        }
        const int *g = G[big][e][j & 1];
        v[0] = 4 * q + 2 * j + g[1]; v[1] = 0; v[2] = r - q - g[2]; *t = g[0];
        *st = (W)g[4] + (W)g[5] * q + (W)g[6] * j + (W)4 * q * q + (W)4 * q * j;
        return (W)3 * q + (W)((j + g[3]) / 2);
    }
    return 0;
}

static void pw(W x, char *buf) {
    char tmp[64]; int n = 0;
    if (!x) { strcpy(buf, "0"); return; }
    while (x) { tmp[n++] = '0' + (int)(x % 10); x /= 10; }
    for (int i = 0; i < n; i++) buf[i] = tmp[n - 1 - i];
    buf[n] = 0;
}

static I hist[2][33][64];
static I h2[2][3][2][33][64];  /* [Y?][e][j odd][R - q + 16][bin] at every zigzag start */
static double hexp[64];        /* sum of 1/(a + j + r) over the zigzag starts in each bin */  /* [Y?][d + 16][bin of log2 passes] */

/* the Lean `passes` of lean/Pass.lean: N calls of pass (fast where it applies, else one jump) */
static int lean_main(I N) {
    int t = z; I v[3] = {0, 0, 2}; W frames = 0; char b1[64];
    for (I i = 0; i < N; i++) {
        W st = 0, k = 0;
        if (zstart(t, v)) k = pass(&t, v, &st);
        if (!k) { int hc = -1; k = jump(&t, v, &st, &hc); if (!k) { printf("HALT\n"); return 0; } }
        frames += k;
    }
    pw(frames, b1);
    printf("passes %lld (Ph.z 0 0 2) 0 = some (.%c %lld %lld %lld, %s)\n", N, TAG[t], v[0], v[1], v[2], b1);
    return 0;
}

/* for py/gen_pass.py: from each "t a j r" on stdin, the jumps to the next zigzag start as [case frames t a j r] */
static int passv_main(void) {
    char tc; long long a, b, c;
    while (scanf(" %c %lld %lld %lld", &tc, &a, &b, &c) == 4) {
        int t = (int)(strchr(TAG, tc) - TAG); I v[3] = {a, b, c}; int n = 0; char bb[64];
        printf("%c %lld %lld %lld :", tc, a, b, c);
        do {
            W s1 = 0; int hc = -1; I k = jump(&t, v, &s1, &hc);
            if (!k) { printf(" HALT"); break; }
            pw((W)k, bb); printf(" [%d %s %c %lld %lld %lld]", lastcode, bb, TAG[t], v[0], v[1], v[2]); n++;
        } while (!zstart(t, v) && n < 100);
        printf(" -> %c %lld %lld %lld\n", TAG[t], v[0], v[1], v[2]);
    }
    return 0;
}

/* scout N EVERY D: the run of `run` with the state only (no frame or step counts, about twice as fast); the lines
   every EVERY passes and the close calls are the same as those of `run` */
static int scout_main(I N, I every, I D) {
    int t = z; I v[3] = {0, 0, 2}; I npass = 0; int slow = 0;
    for (;;) {
        while (!zstart(t, v)) {
            W st; int hc = -1; int t0 = t; I v0[3] = {v[0], v[1], v[2]};
            if (!jump(&t, v, &st, &hc)) { printf("HALT pass %lld case %s from %c(%lld,%lld,%lld)\n", npass, fc_name[hc], TAG[t0], v0[0], v0[1], v0[2]); return 0; }
        }
        if (slow && every && npass % every == 0) { printf("%lld - - %c %lld %lld %lld\n", npass, TAG[t], v[0], v[1], v[2]); fflush(stdout); }
        I a = v[0], j = v[1], r = v[2];
        for (;;) {   /* fast passes in registers */
            if (npass >= N) { v[0] = a; v[1] = j; v[2] = r; goto done; }
            npass++;
            I q = a / 3, e = a - 3 * q;
            if (e == 1 && D >= 0) {
                I d = r - q - (t == Y ? 3 : 2);
                if (d >= -D && d <= D && !(j & 1)) { printf("close pass %lld %c(%lld,%lld,%lld) d %+lld\n", npass, TAG[t], a, j, r, d); fflush(stdout); }
            }
            if (r <= q - 1) { a = a - 3 * r + 1; r = 4 * r + 2 * j + 2; j = 0; }
            else if (r >= q + 7) {
                if (t == Y && e == 2) { a = 5; j = j + 2 * q + 2; r = r - q - 1; t = y; }
                else { const int *g = G[t == Y][e][j & 1]; a = 4 * q + 2 * j + g[1]; j = 0; r = r - q - g[2]; t = g[0]; }
            } else { v[0] = a; v[1] = j; v[2] = r; break; }
            slow = 0;
            if (every && npass % every == 0) {
                if (a > (1LL << 60) || r > (1LL << 60) || j > (1LL << 60)) { printf("OVERFLOW at pass %lld\n", npass); return 2; }
                printf("%lld - - %c %lld %lld %lld\n", npass, TAG[t], a, j, r); fflush(stdout);
            }
        }
        /* near the boundary: the zigzag jump here, then jumps to the next zigzag start */
        { W st; int hc = -1; if (!jump(&t, v, &st, &hc)) { printf("HALT pass %lld\n", npass); return 0; } }
        slow = 1;
    }
done:
    printf("END passes %lld state %c(%lld,%lld,%lld)\n", N, TAG[t], v[0], v[1], v[2]);
    return 0;
}

/* rate: hazard of the halting rows on random orbits (see the header) */
static unsigned long long rng_s;
static unsigned long long rnd(void) { rng_s ^= rng_s << 13; rng_s ^= rng_s >> 7; rng_s ^= rng_s << 17; return rng_s; }
static int rate_main(unsigned long long seed, I M, I P, I N0) {
    rng_s = seed * 2654435761ULL + 88172645463325252ULL;
    I hd[2][33] = {{0}}, halts = 0, hd0halt = 0; double S = 0;
    for (I m = 0; m < M; m++) {
        int t = (rnd() % 3 == 0) ? Y : y; I a = 3 + (I)(rnd() % (unsigned long long)(N0 - 10)); I v[3] = {a, 0, N0 - a};
        I np = 0; int lastd0 = 0;
        while (np < P) {
            if (!zstart(t, v)) {
                W st; int hc = -1;
                if (!jump(&t, v, &st, &hc)) { halts++; hd0halt += lastd0; break; }
                continue;
            }
            np++;
            I a2 = v[0], j = v[1], r = v[2];
            S += 1.0 / (double)(a2 + j + r);
            lastd0 = 0;
            if (a2 % 3 == 1 && !(j & 1)) {
                I d = r - a2 / 3 - (t == Y ? 3 : 2);
                if (d >= -16 && d <= 16) hd[t == Y][d + 16]++;
                lastd0 = d == 0;
            }
            W st = 0;
            if (!pass(&t, v, &st)) { int hc = -1; if (!jump(&t, v, &st, &hc)) { halts++; hd0halt += lastd0; break; } }
        }
    }
    printf("rate seed %llu orbits %lld passes %lld N0 %lld: sum 1/N %.6f halts %lld (%lld right after a d = 0 start)\n",
           seed, M, P, N0, S, halts, hd0halt);
    for (int g = 0; g < 2; g++) { printf("%c:", g ? 'Y' : 'y'); for (int d = 0; d < 33; d++) printf(" %lld", hd[g][d]); printf("\n"); }
    return 0;
}

int main(int argc, char **argv) {
    if (argc >= 6 && !strcmp(argv[1], "rate")) return rate_main(strtoull(argv[2], 0, 10), atoll(argv[3]), atoll(argv[4]), atoll(argv[5]));
    if (argc >= 3 && !strcmp(argv[1], "scout")) return scout_main(atoll(argv[2]), argc > 3 ? atoll(argv[3]) : 0, argc > 4 ? atoll(argv[4]) : -1);
    if (argc >= 2 && !strcmp(argv[1], "passv")) return passv_main();
    if (argc >= 3 && !strcmp(argv[1], "lean")) return lean_main(atoll(argv[2]));
    if (argc < 3) { fprintf(stderr, "usage: prun check|run N [EVERY D]\n"); return 1; }
    int check = !strcmp(argv[1], "check");
    I N = atoll(argv[2]), every = argc > 3 ? atoll(argv[3]) : 0, D = argc > 4 ? atoll(argv[4]) : -1;
    int t = z; I v[3] = {0, 0, 2};
    W frames = 0, steps = 2, jumps = 0;
    char b1[64], b2[64], b3[64];
    I npass = 0, nfast = 0;
    W stopF = 0; if (getenv("STOPF")) { const char *p = getenv("STOPF"); while (*p) stopF = stopF * 10 + (*p++ - '0'); }
    for (;;) {
        if (stopF && frames >= stopF) { pw(frames, b1); pw(steps, b2); printf("AT frames %s steps %s state %c(%lld,%lld,%lld) passes %lld\n", b1, b2, TAG[t], v[0], v[1], v[2], npass); return 0; }
        /* go to the next zigzag start by jumps (also the slow passes near the boundary) */
        if (!zstart(t, v)) {
            W st = 0; int hc = -1; int t0 = t; I v0[3] = {v[0], v[1], v[2]};
            I k = jump(&t, v, &st, &hc); jumps++;
            if (!k) {
                frames += 1; steps += st; pw(frames, b1); pw(steps, b2);
                printf("HALT pass %lld frame %s steps %s case %s from %c(%lld,%lld,%lld)\n", npass, b1, b2, fc_name[hc], TAG[t0], v0[0], v0[1], v0[2]);
                return 0;
            }
            frames += k; steps += st;
            if (!zstart(t, v)) continue;
        }
        /* at a zigzag start: the end of pass npass and the start of pass npass + 1 */
        if (every && npass && npass % every == 0) {
            pw(frames, b1); pw(steps, b2); pw(jumps, b3);
            printf("%lld %s %s %c %lld %lld %lld fast %lld slowjumps %s\n", npass, b1, b2, TAG[t], v[0], v[1], v[2], nfast, b3); fflush(stdout);
        }
        if (npass >= N) break;
        npass++;
        I a = v[0], j = v[1], r = v[2];
        { I dl = r - a / 3; int bin = 0; I m = npass; while (m > 1) { bin++; m >>= 1; }
          hexp[bin] += 1.0 / (double)(a + j + r);
          if (dl >= -16 && dl <= 16) h2[t == Y][a % 3][j & 1][dl + 16][bin]++; }
        if (a % 3 == 1 && !(j & 1)) {
            I d = r - a / 3 - (t == Y ? 3 : 2);
            if (d >= -16 && d <= 16) {
                int bin = 0; I m = npass; while (m > 1) { bin++; m >>= 1; }
                hist[t == Y][d + 16][bin]++;
                if (D >= 0 && (d < 0 ? -d : d) <= D) { printf("close pass %lld %c(%lld,%lld,%lld) d %+lld\n", npass, TAG[t], a, j, r, d); fflush(stdout); }
            }
        }
        if (steps > ((W)1 << 126)) { printf("OVERFLOW (steps) at pass %lld\n", npass); return 2; }
        if (a > (1LL << 60) || r > (1LL << 60) || j > (1LL << 60)) { printf("OVERFLOW at pass %lld\n", npass); return 2; }
        int t0 = t; I v0[3] = {a, j, r}; W st = 0;
        W k = pass(&t, v, &st);
        if (k) {
            nfast++;
            if (check) {  /* the same pass by jumps */
                int tt = t0; I vv[3] = {v0[0], v0[1], v0[2]}; W fr = 0, s2 = 0;
                do { W s1 = 0; int hc = -1; I kk = jump(&tt, vv, &s1, &hc);
                     if (!kk) { printf("MISMATCH halt inside pass %lld\n", npass); return 1; }
                     fr += kk; s2 += s1; } while (!zstart(tt, vv));
                if (tt != t || vv[0] != v[0] || vv[1] != v[1] || vv[2] != v[2] || fr != k || s2 != st) {
                    printf("MISMATCH pass %lld from %c(%lld,%lld,%lld)\n", npass, TAG[t0], v0[0], v0[1], v0[2]); return 1; }
            }
            frames += k; steps += st;
        } else {
            /* near the boundary: take the zigzag jump here, then the loop continues by jumps */
            W st2 = 0; int hc = -1;
            I kk = jump(&t, v, &st2, &hc); jumps++;
            frames += kk; steps += st2;
        }
    }
    pw(frames, b1); pw(steps, b2);
    printf("END passes %lld frames %s steps %s state %c(%lld,%lld,%lld) fast %lld\n", N, b1, b2, TAG[t], v[0], v[1], v[2], nfast);
    if (D >= 0) {
        printf("hexp:"); for (int b = 0; b < 64; b++) printf(" %.6g", hexp[b]); printf("\n");
        for (int g = 0; g < 2; g++) for (int e = 0; e < 3; e++) for (int p = 0; p < 2; p++) for (int d = 0; d < 33; d++) {
            I tot = 0; for (int b = 0; b < 64; b++) tot += h2[g][e][p][d][b];
            if (!tot) continue;
            printf("h2 %c e%d j%d R-q %+d:", g ? 'Y' : 'y', e, p, d - 16);
            for (int b = 0; b < 64; b++) printf(" %lld", h2[g][e][p][d][b]);
            printf("\n");
        }
        printf("hist: zigzag starts with a = 1 mod 3, j even, by d (rows) and floor(log2 pass) (columns)\n");
        for (int g = 0; g < 2; g++) for (int d = 0; d < 33; d++) {
            printf("%c %+d:", g ? 'Y' : 'y', d - 16);
            for (int b = 0; b < 64; b++) printf(" %lld", hist[g][d][b]);
            printf("\n");
        }
    }
    return 0;
}
